from pathlib import Path


def carregar_landing() -> str:
    public_index = Path(__file__).resolve().parent.parent / "public" / "index.html"
    if public_index.exists():
        return public_index.read_text(encoding="utf-8")
    return FALLBACK_LANDING_HTML


FALLBACK_LANDING_HTML = "<!doctype html>\n<html lang=\"pt-BR\">\n  <head>\n    <meta charset=\"UTF-8\" />\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n    <title>No Meu Ritmo!</title>\n    <script src=\"https://cdn.tailwindcss.com\"></script>\n    <script src=\"https://cdnjs.cloudflare.com/ajax/libs/jspdf/2.5.1/jspdf.umd.min.js\"></script>\n  </head>\n  <body class=\"bg-neutral-100 text-neutral-950 antialiased\">\n    <main class=\"mx-auto min-h-screen w-full max-w-7xl px-4 py-4 sm:px-6 lg:px-8\">\n      <header class=\"mb-5 flex flex-col gap-3 border-b border-neutral-300 pb-4 sm:flex-row sm:items-center sm:justify-between\">\n        <div>\n          <p class=\"text-xs font-semibold uppercase tracking-[0.22em] text-neutral-500\">Painel de estudos</p>\n          <h1 class=\"text-2xl font-semibold tracking-tight\">No Meu Ritmo!</h1>\n        </div>\n        <nav class=\"flex flex-wrap gap-2\">\n          <a class=\"rounded-md border border-neutral-300 bg-white px-3 py-2 text-sm font-medium hover:bg-neutral-50\" href=\"/apidocs/\">Swagger</a>\n          <a class=\"rounded-md border border-neutral-300 bg-white px-3 py-2 text-sm font-medium hover:bg-neutral-50\" href=\"/api/materias\">API</a>\n          <button id=\"downloadPdfButton\" class=\"rounded-md border border-neutral-300 bg-white px-3 py-2 text-sm font-medium hover:bg-neutral-50\">Baixar PDF</button>\n          <button id=\"refreshButton\" class=\"rounded-md bg-neutral-950 px-3 py-2 text-sm font-medium text-white hover:bg-neutral-800\">Atualizar</button>\n        </nav>\n      </header>\n\n      <section class=\"mb-5 grid gap-3 sm:grid-cols-2 lg:grid-cols-4\">\n        <article class=\"border border-neutral-300 bg-white p-4\">\n          <p class=\"text-xs font-medium uppercase tracking-wide text-neutral-500\">Tempo planejado</p>\n          <strong id=\"plannedMinutes\" class=\"mt-2 block text-3xl font-semibold\">0 min</strong>\n        </article>\n        <article class=\"border border-neutral-300 bg-white p-4\">\n          <p class=\"text-xs font-medium uppercase tracking-wide text-neutral-500\">Tempo registrado</p>\n          <strong id=\"doneMinutes\" class=\"mt-2 block text-3xl font-semibold\">0 min</strong>\n        </article>\n        <article class=\"border border-neutral-300 bg-white p-4\">\n          <p class=\"text-xs font-medium uppercase tracking-wide text-neutral-500\">Foco médio</p>\n          <strong id=\"avgFocus\" class=\"mt-2 block text-3xl font-semibold\">-</strong>\n        </article>\n        <article class=\"border border-neutral-300 bg-white p-4\">\n          <p class=\"text-xs font-medium uppercase tracking-wide text-neutral-500\">Sessões</p>\n          <strong id=\"sessionCount\" class=\"mt-2 block text-3xl font-semibold\">0</strong>\n        </article>\n      </section>\n\n      <section class=\"grid gap-5 lg:grid-cols-[1.15fr_0.85fr]\">\n        <div class=\"space-y-5\">\n          <section class=\"border border-neutral-300 bg-white p-4\">\n            <div class=\"mb-4 flex items-center justify-between gap-3\">\n              <div>\n                <h2 class=\"text-lg font-semibold\">Plano de hoje</h2>\n                <p class=\"text-sm text-neutral-600\">Use estes blocos como referência e registre o que realmente estudou.</p>\n              </div>\n            </div>\n            <div id=\"planList\" class=\"grid gap-3 md:grid-cols-3\"></div>\n          </section>\n\n          <section class=\"border border-neutral-300 bg-white p-4\">\n            <h2 class=\"text-lg font-semibold\">Matérias</h2>\n            <form id=\"subjectForm\" class=\"mt-4 grid gap-3 border-b border-neutral-200 pb-4 md:grid-cols-[1fr_140px_90px_auto]\">\n              <input id=\"subjectId\" type=\"hidden\" />\n              <input id=\"subjectName\" class=\"rounded-md border border-neutral-300 px-3 py-2 outline-none focus:border-neutral-950\" placeholder=\"Nova matéria\" required minlength=\"2\" />\n              <select id=\"subjectPriority\" class=\"rounded-md border border-neutral-300 px-3 py-2 outline-none focus:border-neutral-950\">\n                <option value=\"media\">Média</option>\n                <option value=\"alta\">Alta</option>\n                <option value=\"baixa\">Baixa</option>\n              </select>\n              <input id=\"subjectColor\" type=\"color\" value=\"#2563eb\" class=\"h-10 w-full rounded-md border border-neutral-300 bg-white px-2\" />\n              <button class=\"rounded-md bg-neutral-950 px-4 py-2 text-sm font-semibold text-white hover:bg-neutral-800\" type=\"submit\">Salvar</button>\n              <input id=\"subjectDescription\" class=\"rounded-md border border-neutral-300 px-3 py-2 outline-none focus:border-neutral-950 md:col-span-3\" placeholder=\"Descrição curta\" />\n              <button id=\"cancelSubjectEdit\" class=\"hidden rounded-md border border-neutral-300 bg-white px-4 py-2 text-sm font-medium hover:bg-neutral-50\" type=\"button\">Cancelar</button>\n            </form>\n            <div id=\"subjectList\" class=\"mt-4 grid gap-3 sm:grid-cols-2\"></div>\n          </section>\n        </div>\n\n        <aside class=\"space-y-5\">\n          <section class=\"border border-neutral-300 bg-white p-4\">\n            <h2 class=\"text-lg font-semibold\">Registrar sessão</h2>\n            <form id=\"sessionForm\" class=\"mt-4 space-y-3\">\n              <label class=\"block\">\n                <span class=\"text-sm font-medium\">Matéria</span>\n                <input id=\"materia\" name=\"materia\" required minlength=\"2\" class=\"mt-1 w-full rounded-md border border-neutral-300 px-3 py-2 outline-none focus:border-neutral-950\" placeholder=\"Ex: Cálculo, Redes, Programação Web\" />\n              </label>\n              <div class=\"grid grid-cols-2 gap-3\">\n                <label class=\"block\">\n                  <span class=\"text-sm font-medium\">Tipo</span>\n                  <select id=\"tipo_estudo\" name=\"tipo_estudo\" class=\"mt-1 w-full rounded-md border border-neutral-300 px-3 py-2 outline-none focus:border-neutral-950\">\n                    <option value=\"projeto\">Projeto</option>\n                    <option value=\"exercicios\">Exercícios</option>\n                    <option value=\"revisao\">Revisão</option>\n                    <option value=\"leitura\">Leitura</option>\n                  </select>\n                </label>\n                <label class=\"block\">\n                  <span class=\"text-sm font-medium\">Foco</span>\n                  <select id=\"nivel_foco\" name=\"nivel_foco\" class=\"mt-1 w-full rounded-md border border-neutral-300 px-3 py-2 outline-none focus:border-neutral-950\">\n                    <option value=\"5\">5</option>\n                    <option value=\"4\" selected>4</option>\n                    <option value=\"3\">3</option>\n                    <option value=\"2\">2</option>\n                    <option value=\"1\">1</option>\n                  </select>\n                </label>\n              </div>\n              <label class=\"block\">\n                <span class=\"text-sm font-medium\">Duração em minutos</span>\n                <input id=\"duracao_minutos\" name=\"duracao_minutos\" required type=\"number\" min=\"1\" max=\"300\" value=\"40\" class=\"mt-1 w-full rounded-md border border-neutral-300 px-3 py-2 outline-none focus:border-neutral-950\" />\n              </label>\n              <label class=\"block\">\n                <span class=\"text-sm font-medium\">Observação</span>\n                <textarea id=\"observacao\" name=\"observacao\" rows=\"3\" maxlength=\"240\" class=\"mt-1 w-full rounded-md border border-neutral-300 px-3 py-2 outline-none focus:border-neutral-950\" placeholder=\"O que você estudou?\"></textarea>\n              </label>\n              <button class=\"w-full rounded-md bg-neutral-950 px-4 py-3 text-sm font-semibold text-white hover:bg-neutral-800\" type=\"submit\">Salvar sessão</button>\n              <p id=\"feedback\" class=\"min-h-5 text-sm font-medium\"></p>\n            </form>\n          </section>\n\n          <section class=\"border border-neutral-300 bg-white p-4\">\n            <h2 class=\"text-lg font-semibold\">Histórico</h2>\n            <div id=\"sessionList\" class=\"mt-4 max-h-[430px] space-y-3 overflow-auto pr-1\"></div>\n          </section>\n        </aside>\n      </section>\n\n    </main>\n\n    <script>\n      const state = { materias: [], plano: [], sessoes: [] };\n      const $ = (id) => document.getElementById(id);\n      const storageKey = \"no-meu-ritmo-sessoes\";\n      const subjectStorageKey = \"no-meu-ritmo-materias\";\n\n      function localSessions() {\n        try {\n          return JSON.parse(localStorage.getItem(storageKey) || \"[]\");\n        } catch {\n          return [];\n        }\n      }\n\n      function saveLocalSessions(sessoes) {\n        localStorage.setItem(storageKey, JSON.stringify(sessoes));\n      }\n\n      function localSubjects() {\n        try {\n          return JSON.parse(localStorage.getItem(subjectStorageKey) || \"[]\");\n        } catch {\n          return [];\n        }\n      }\n\n      function saveLocalSubjects(materias) {\n        localStorage.setItem(subjectStorageKey, JSON.stringify(materias));\n      }\n\n      function mergeSubjects(apiSubjects, browserSubjects, sessoes) {\n        const byName = new Map();\n        [...apiSubjects, ...browserSubjects].forEach((materia) => {\n          if (!materia.nome) return;\n          byName.set(materia.nome, { ...materia, total_minutos: 0, total_sessoes: 0 });\n        });\n        sessoes.forEach((sessao) => {\n          const nome = sessao.materia;\n          if (!nome) return;\n          if (!byName.has(nome)) {\n            byName.set(nome, {\n              id: Date.now() + byName.size,\n              nome,\n              prioridade: \"media\",\n              cor: colorForName(nome),\n              descricao: \"\",\n              total_minutos: 0,\n              total_sessoes: 0\n            });\n          }\n          const materia = byName.get(nome);\n          materia.total_minutos += Number(sessao.duracao_minutos || 0);\n          materia.total_sessoes += 1;\n        });\n        return [...byName.values()];\n      }\n\n      function mergeSessions(apiSessions, browserSessions) {\n        const seen = new Set();\n        return [...apiSessions, ...browserSessions].filter((sessao) => {\n          const key = [\n            sessao.id,\n            sessao.materia,\n            sessao.tipo_estudo,\n            sessao.duracao_minutos,\n            sessao.nivel_foco,\n            sessao.observacao,\n            sessao.data_registro\n          ].join(\"|\");\n          if (seen.has(key)) return false;\n          seen.add(key);\n          return true;\n        });\n      }\n\n      function escapeHtml(value) {\n        return String(value ?? \"\").replace(/[&<>\"']/g, (char) => ({\n          \"&\": \"&amp;\",\n          \"<\": \"&lt;\",\n          \">\": \"&gt;\",\n          '\"': \"&quot;\",\n          \"'\": \"&#039;\"\n        })[char]);\n      }\n\n      async function getJson(path) {\n        const response = await fetch(path);\n        if (!response.ok) throw new Error(`Erro ${response.status}`);\n        return response.json();\n      }\n\n      function renderStats() {\n        const planned = state.plano.reduce((total, item) => total + Number(item.duracao_minutos || 0), 0);\n        const done = state.sessoes.reduce((total, item) => total + Number(item.duracao_minutos || 0), 0);\n        const focusValues = state.sessoes.map((item) => Number(item.nivel_foco || 0)).filter(Boolean);\n        const avg = focusValues.length ? (focusValues.reduce((a, b) => a + b, 0) / focusValues.length).toFixed(1) : \"-\";\n        $(\"plannedMinutes\").textContent = `${planned} min`;\n        $(\"doneMinutes\").textContent = `${done} min`;\n        $(\"avgFocus\").textContent = avg;\n        $(\"sessionCount\").textContent = state.sessoes.length;\n      }\n\n      function renderPlano() {\n        if (!state.plano.length) {\n          $(\"planList\").innerHTML = '<p class=\"text-sm text-neutral-600 md:col-span-3\">Registre uma sessão para gerar sugestões de plano com base no seu histórico real.</p>';\n          return;\n        }\n        $(\"planList\").innerHTML = state.plano.map((item) => `\n          <article class=\"border border-neutral-200 p-3\">\n            <div class=\"flex items-center justify-between text-sm\">\n              <strong>${escapeHtml(item.horario)}</strong>\n              <span class=\"text-neutral-500\">${escapeHtml(item.duracao_minutos)} min</span>\n            </div>\n            <h3 class=\"mt-3 font-semibold\">${escapeHtml(item.materia)}</h3>\n            <p class=\"mt-1 text-sm text-neutral-600\">${escapeHtml(item.meta)}</p>\n            <button class=\"mt-3 rounded-md border border-neutral-300 px-3 py-2 text-sm font-medium hover:bg-neutral-50\" data-plan=\"${escapeHtml(item.materia)}\" data-type=\"${escapeHtml(item.tipo)}\" data-duration=\"${escapeHtml(item.duracao_minutos)}\">Usar no formulário</button>\n          </article>\n        `).join(\"\");\n      }\n\n      function renderMaterias() {\n        if (!state.materias.length) {\n          $(\"subjectList\").innerHTML = '<p class=\"text-sm text-neutral-600 sm:col-span-2\">Nenhuma matéria ainda. Ao salvar uma sessão, a matéria aparece aqui automaticamente.</p>';\n          return;\n        }\n        $(\"subjectList\").innerHTML = state.materias.map((item) => `\n          <article class=\"border border-neutral-200 p-3\">\n            <div class=\"flex items-center gap-2\">\n              <span class=\"h-3 w-3 rounded-full\" style=\"background:${escapeHtml(item.cor)}\"></span>\n              <h3 class=\"font-semibold\">${escapeHtml(item.nome)}</h3>\n              <span class=\"ml-auto rounded-full bg-neutral-100 px-2 py-1 text-xs text-neutral-600\">${escapeHtml(item.prioridade)}</span>\n            </div>\n            <p class=\"mt-2 text-sm text-neutral-600\">${escapeHtml(item.descricao)}</p>\n            <div class=\"mt-3 flex gap-2\">\n              <button class=\"rounded-md border border-neutral-300 px-3 py-2 text-sm font-medium hover:bg-neutral-50\" data-edit-subject=\"${escapeHtml(item.id)}\">Editar</button>\n              <button class=\"rounded-md border border-red-200 px-3 py-2 text-sm font-medium text-red-700 hover:bg-red-50\" data-delete-subject=\"${escapeHtml(item.id)}\">Excluir</button>\n            </div>\n          </article>\n        `).join(\"\");\n      }\n\n      function renderSessoes() {\n        if (!state.sessoes.length) {\n          $(\"sessionList\").innerHTML = '<p class=\"text-sm text-neutral-600\">Nenhuma sessão registrada ainda.</p>';\n          return;\n        }\n        $(\"sessionList\").innerHTML = [...state.sessoes].reverse().map((item) => `\n          <article class=\"border border-neutral-200 p-3\">\n            <div class=\"flex items-start justify-between gap-3\">\n              <div>\n                <h3 class=\"font-semibold\">${escapeHtml(item.materia || item.nome || \"Matéria\")}</h3>\n                <p class=\"text-sm text-neutral-600\">${escapeHtml(item.tipo_estudo)} · ${escapeHtml(item.duracao_minutos)} min · foco ${escapeHtml(item.nivel_foco)}</p>\n              </div>\n              <span class=\"text-xs text-neutral-500\">${escapeHtml(item.data_registro || \"\")}</span>\n            </div>\n            ${item.observacao ? `<p class=\"mt-2 text-sm text-neutral-700\">${escapeHtml(item.observacao)}</p>` : \"\"}\n          </article>\n        `).join(\"\");\n      }\n\n      function renderAll() {\n        renderStats();\n        renderPlano();\n        renderMaterias();\n        renderSessoes();\n      }\n\n      async function loadData() {\n        $(\"feedback\").textContent = \"\";\n        const results = await Promise.allSettled([\n          getJson(\"/api/materias\"),\n          getJson(\"/api/plano-hoje\"),\n          getJson(\"/api/sessoes\")\n        ]);\n        const apiSessions = results[2].status === \"fulfilled\" ? results[2].value : [];\n        state.sessoes = mergeSessions(apiSessions, localSessions());\n        const apiSubjects = results[0].status === \"fulfilled\" ? results[0].value : [];\n        state.materias = mergeSubjects(apiSubjects, localSubjects(), state.sessoes);\n        state.plano = buildPlan(state.materias);\n        renderAll();\n        if (results.some((result) => result.status === \"rejected\")) {\n          $(\"feedback\").className = \"min-h-5 text-sm font-medium text-amber-700\";\n          $(\"feedback\").textContent = \"Alguns dados não carregaram agora. Você ainda pode registrar uma sessão.\";\n        }\n      }\n\n      document.addEventListener(\"click\", (event) => {\n        const editButton = event.target.closest(\"[data-edit-subject]\");\n        if (editButton) {\n          const subject = state.materias.find((item) => String(item.id) === String(editButton.dataset.editSubject));\n          if (!subject) return;\n          $(\"subjectId\").value = subject.id;\n          $(\"subjectName\").value = subject.nome;\n          $(\"subjectPriority\").value = subject.prioridade || \"media\";\n          $(\"subjectColor\").value = subject.cor || \"#2563eb\";\n          $(\"subjectDescription\").value = subject.descricao || \"\";\n          $(\"cancelSubjectEdit\").classList.remove(\"hidden\");\n          return;\n        }\n\n        const deleteButton = event.target.closest(\"[data-delete-subject]\");\n        if (deleteButton) {\n          const id = deleteButton.dataset.deleteSubject;\n          saveLocalSubjects(localSubjects().filter((item) => String(item.id) !== String(id)));\n          fetch(`/api/materias/${id}`, { method: \"DELETE\" }).catch(() => {});\n          loadData();\n          return;\n        }\n\n        const button = event.target.closest(\"[data-plan]\");\n        if (!button) return;\n        $(\"materia\").value = button.dataset.plan;\n        $(\"tipo_estudo\").value = button.dataset.type || \"projeto\";\n        $(\"duracao_minutos\").value = button.dataset.duration || 40;\n        $(\"observacao\").focus();\n      });\n\n      $(\"cancelSubjectEdit\").addEventListener(\"click\", () => {\n        $(\"subjectForm\").reset();\n        $(\"subjectId\").value = \"\";\n        $(\"subjectColor\").value = \"#2563eb\";\n        $(\"cancelSubjectEdit\").classList.add(\"hidden\");\n      });\n\n      $(\"subjectForm\").addEventListener(\"submit\", async (event) => {\n        event.preventDefault();\n        const id = $(\"subjectId\").value || String(Date.now());\n        let materia = {\n          id,\n          nome: $(\"subjectName\").value.trim(),\n          prioridade: $(\"subjectPriority\").value,\n          cor: $(\"subjectColor\").value,\n          descricao: $(\"subjectDescription\").value.trim() || \"\"\n        };\n        const method = $(\"subjectId\").value ? \"PUT\" : \"POST\";\n        const path = $(\"subjectId\").value ? `/api/materias/${id}` : \"/api/materias\";\n        try {\n          const response = await fetch(path, {\n            method,\n            headers: { \"Content-Type\": \"application/json\" },\n            body: JSON.stringify(materia)\n          });\n          const data = await response.json();\n          if (response.ok && data.materia) {\n            materia = data.materia;\n          }\n        } catch {}\n        const local = localSubjects().filter((item) => String(item.id) !== String(id) && item.nome !== materia.nome);\n        local.push(materia);\n        saveLocalSubjects(local);\n        $(\"subjectForm\").reset();\n        $(\"subjectId\").value = \"\";\n        $(\"subjectColor\").value = \"#2563eb\";\n        $(\"cancelSubjectEdit\").classList.add(\"hidden\");\n        await loadData();\n      });\n\n      $(\"sessionForm\").addEventListener(\"submit\", async (event) => {\n        event.preventDefault();\n        const payload = {\n          materia: $(\"materia\").value.trim(),\n          tipo_estudo: $(\"tipo_estudo\").value,\n          duracao_minutos: Number($(\"duracao_minutos\").value),\n          nivel_foco: Number($(\"nivel_foco\").value),\n          observacao: $(\"observacao\").value.trim() || null\n        };\n        $(\"feedback\").className = \"min-h-5 text-sm font-medium text-neutral-600\";\n        $(\"feedback\").textContent = \"Salvando...\";\n        try {\n          const response = await fetch(\"/api/sessoes\", {\n            method: \"POST\",\n            headers: { \"Content-Type\": \"application/json\" },\n            body: JSON.stringify(payload)\n          });\n          const data = await response.json();\n          if (!response.ok) throw new Error(data.erro || \"Não foi possível salvar.\");\n          $(\"feedback\").className = \"min-h-5 text-sm font-medium text-emerald-700\";\n          $(\"feedback\").textContent = data.mensagem || \"Sessão salva.\";\n          $(\"observacao\").value = \"\";\n          saveLocalSessions(mergeSessions(localSessions(), [data.sessao]));\n          await loadData();\n        } catch (error) {\n          $(\"feedback\").className = \"min-h-5 text-sm font-medium text-red-700\";\n          $(\"feedback\").textContent = error.message;\n        }\n      });\n\n      $(\"refreshButton\").addEventListener(\"click\", loadData);\n      $(\"downloadPdfButton\").addEventListener(\"click\", () => {\n        const { jsPDF } = window.jspdf || {};\n        if (!jsPDF) {\n          window.location.href = \"/api/relatorio.pdf\";\n          return;\n        }\n        const doc = new jsPDF();\n        const total = state.sessoes.reduce((sum, item) => sum + Number(item.duracao_minutos || 0), 0);\n        const focos = state.sessoes.map((item) => Number(item.nivel_foco || 0)).filter(Boolean);\n        const focoMedio = focos.length ? (focos.reduce((a, b) => a + b, 0) / focos.length).toFixed(1) : \"-\";\n        let y = 18;\n        doc.setFont(\"helvetica\", \"bold\");\n        doc.setFontSize(16);\n        doc.text(\"No Meu Ritmo - Relatorio de Estudos\", 14, y);\n        y += 10;\n        doc.setFont(\"helvetica\", \"normal\");\n        doc.setFontSize(11);\n        doc.text(`Gerado em ${new Date().toLocaleDateString(\"pt-BR\")}`, 14, y);\n        y += 12;\n        doc.text(`Sessoes: ${state.sessoes.length}`, 14, y);\n        doc.text(`Tempo total: ${total} min`, 75, y);\n        doc.text(`Foco medio: ${focoMedio}`, 145, y);\n        y += 14;\n        doc.setFont(\"helvetica\", \"bold\");\n        doc.text(\"Historico\", 14, y);\n        y += 8;\n        doc.setFont(\"helvetica\", \"normal\");\n        if (!state.sessoes.length) {\n          doc.text(\"Nenhuma sessao registrada ainda.\", 14, y);\n        } else {\n          state.sessoes.forEach((sessao) => {\n            if (y > 275) {\n              doc.addPage();\n              y = 18;\n            }\n            const linha = `${sessao.data_registro || \"\"} - ${sessao.materia || \"Materia\"} - ${sessao.tipo_estudo || \"\"} - ${sessao.duracao_minutos || 0} min - foco ${sessao.nivel_foco || \"-\"}`;\n            doc.text(linha, 14, y);\n            y += 6;\n            if (sessao.observacao) {\n              doc.text(doc.splitTextToSize(String(sessao.observacao), 180), 14, y);\n              y += 10;\n            }\n          });\n        }\n        doc.save(`relatorio-no-meu-ritmo-${new Date().toISOString().slice(0, 10)}.pdf`);\n      });\n      loadData().catch((error) => {\n        $(\"feedback\").className = \"min-h-5 text-sm font-medium text-red-700\";\n        $(\"feedback\").textContent = `Erro ao carregar dados: ${error.message}`;\n      });\n\n      function buildPlan(materias) {\n        const horarios = [\"18:30\", \"19:20\", \"20:10\"];\n        return [...materias]\n          .sort((a, b) => Number(a.total_minutos || 0) - Number(b.total_minutos || 0))\n          .slice(0, 3)\n          .map((materia, index) => ({\n            id: index + 1,\n            horario: horarios[index],\n            materia: materia.nome,\n            tipo: Number(materia.total_minutos || 0) > 0 ? \"revisao\" : \"projeto\",\n            duracao_minutos: 40,\n            meta: Number(materia.total_minutos || 0) > 0\n              ? `Continuar ${materia.nome} com base no histórico.`\n              : `Começar ${materia.nome} hoje.`\n          }));\n      }\n\n      function colorForName(nome) {\n        const colors = [\"#2563eb\", \"#16a34a\", \"#dc2626\", \"#9333ea\", \"#0f766e\", \"#ca8a04\"];\n        return colors[[...nome].reduce((sum, char) => sum + char.charCodeAt(0), 0) % colors.length];\n      }\n    </script>\n  </body>\n</html>\n"
